                    $collComInternas->getInternalIterator()->rewind();

                    return $collComInternas;
                }

                if ($partial && $this->collComInternas) {
                    foreach ($this->collComInternas as $obj) {
                        if ($obj->isNew()) {
                            $collComInternas[] = $obj;
                        }
                    }
                }

                $this->collComInternas = $collComInternas;
