     * and new objects from the given Propel collection.
     *
     * @param PropelCollection $comInternas A Propel collection.
     * @param PropelPDO $con Optional connection object
     * @return TipoComInterna The current object (for fluent API support)
     */
    public function setComInternas(PropelCollection $comInternas, PropelPDO $con = null)
    {
        $comInternasToDelete = $this->getComInternas(new Criteria(), $con)->diff($comInternas);


        $this->comInternasScheduledForDeletion = $comInternasToDelete;

        foreach ($comInternasToDelete as $comInternaRemoved) {
            $comInternaRemoved->setTipoComInterna(null);
        }

        $this->collComInternas = null;
        foreach ($comInternas as $comInterna) {
            $this->addComInterna($comInterna);
        }

        $this->collComInternas = $comInternas;
        $this->collComInternasPartial = false;

        return $this;
    }

    /**
     * Returns the number of related ComInterna objects.
     *
     * @param Criteria $criteria
     * @param boolean $distinct
     * @param PropelPDO $con
     * @return int             Count of related ComInterna objects.
     * @throws PropelException
     */
    public function countComInternas(Criteria $criteria = null, $distinct = false, PropelPDO $con = null)
    {
        $partial = $this->collComInternasPartial && !$this->isNew();
        if (null === $this->collComInternas || null !== $criteria || $partial) {
            if ($this->isNew() && null === $this->collComInternas) {
                return 0;
            }

            if ($partial && !$criteria) {
                return count($this->getComInternas());
            }
            $query = ComInternaQuery::create(null, $criteria);
            if ($distinct) {
                $query->distinct();
            }

            return $query
                ->filterByTipoComInterna($this)
                ->count($con);
        }

        return count($this->collComInternas);
    }

    /**
     * Method called to associate a ComInterna object to this object
     * through the ComInterna foreign key attribute.
     *
     * @param    ComInterna $l ComInterna
     * @return TipoComInterna The current object (for fluent API support)
     */
    public function addComInterna(ComInterna $l)
    {
        if ($this->collComInternas === null) {
            $this->initComInternas();
            $this->collComInternasPartial = true;
        }

        if (!in_array($l, $this->collComInternas->getArrayCopy(), true)) { // only add it if the **same** object is not already associated
            $this->doAddComInterna($l);

            if ($this->comInternasScheduledForDeletion and $this->comInternasScheduledForDeletion->contains($l)) {
                $this->comInternasScheduledForDeletion->remove($this->comInternasScheduledForDeletion->search($l));
            }
        }

        return $this;
    }

    /**
     * @param	ComInterna $comInterna The comInterna object to add.
     */
    protected function doAddComInterna($comInterna)
    {
        $this->collComInternas[]= $comInterna;
        $comInterna->setTipoComInterna($this);
    }

    /**
     * @param	ComInterna $comInterna The comInterna object to remove.
     * @return TipoComInterna The current object (for fluent API support)
     */
    public function removeComInterna($comInterna)
    {
        if ($this->getComInternas()->contains($comInterna)) {
            $this->collComInternas->remove($this->collComInternas->search($comInterna));
            if (null === $this->comInternasScheduledForDeletion) {
                $this->comInternasScheduledForDeletion = clone $this->collComInternas;
                $this->comInternasScheduledForDeletion->clear();
            }
            $this->comInternasScheduledForDeletion[]= clone $comInterna;
            $comInterna->setTipoComInterna(null);
        }

        return $this;
    }


